-- Airlinerra business licence/permission research catalogue, 2026-11-08.
-- This migration is intentionally planning-only. No licence, right, application,
-- charge or company is granted. Verified operating rights remain per operator/market.
create table if not exists airlinerra_game.business_permission_catalog_v1 (
 permission_code text primary key check(permission_code ~ '^[A-Z][A-Z0-9_]{2,79}$'),
 category text not null check (category in ('company','airline','maintenance','traffic_rights')),
 holder_scope text not null check(holder_scope in ('holding','operating_company','route')),
 reference_basis text not null check(reference_basis in ('game_proposal','eu_reference','jurisdiction_research')),
 title text not null check(char_length(title) between 5 and 140),
 purpose text not null,
 requirements text not null,
 application_guidance text not null,
 source_url text,
 research_status text not null default 'reference_only' check(research_status in ('reference_only','needs_local_verification')),
 game_fee_usd numeric(14,2) check(game_fee_usd>=0),
 processing_game_days integer check(processing_game_days>=0),
 enabled_in_game boolean not null default false check(enabled_in_game=false),
 updated_at timestamptz not null default now()
);
comment on table airlinerra_game.business_permission_catalog_v1 is
'Reference-only business, aviation, maintenance and market permission templates; never an owned licence or route authority.';
alter table airlinerra_game.business_permission_catalog_v1 enable row level security;
revoke all on airlinerra_game.business_permission_catalog_v1 from public,anon,authenticated;
insert into airlinerra_game.business_permission_catalog_v1
 (permission_code,category,holder_scope,reference_basis,title,purpose,requirements,application_guidance,source_url,research_status,game_fee_usd,processing_game_days,enabled_in_game)
values
('AIR_OPERATOR_CERTIFICATE','airline','operating_company','eu_reference','Air Operator Certificate (AOC)','Authorises the specified commercial air transport operations and aircraft/operational scope. Separate subsidiaries need appropriate operator approval.','Safety management, nominated personnel, manuals, aircraft and operating procedures must meet the competent authority''s rules.','Apply to the State of Operator''s aviation authority (or responsible EASA authority where relevant); complete certification checks.','https://www.easa.europa.eu/en/domains/air-operations/air-operator-certificate-aoc','reference_only',NULL,NULL,false),
('CABOTAGE','traffic_rights','route','jurisdiction_research','Foreign domestic / cabotage rights','Commercial domestic service wholly within a foreign country is not generally available without special or integrated-market rights.','Explicit eighth/ninth freedom or equivalent market right; relevant local operating authorisation.','Verify the airline''s own legal domicile and relevant bilateral or integrated-market privileges before enabling the domestic foreign route.','https://www.icao.int/sustainability/Documents/Compendium_FairCompetition/the%20evolution%20of%20network%20competution%20in%20transtl%20aviation%20and%20the%20effects%20of%20regulatoty%20libveralisatino%202009.pdf','needs_local_verification',NULL,NULL,false),
('CARGO_OPERATIONS_SCOPE','airline','operating_company','jurisdiction_research','Cargo operations scope','Cargo airlines are commercial air carriers: cargo operations must be covered by their applicable licences, AOC and operating specifications.','Applicable commercial air transport approval; approved cargo loading, staff, handling, security and aircraft capability.','Check the existing AOC and operating-licence scope; seek a variation if the company''s approved operations do not cover planned freight.','https://www.easa.europa.eu/en/domains/air-operations/air-operator-certificate-aoc','needs_local_verification',NULL,NULL,false),
('CHARTER_VIP_SCOPE','airline','operating_company','jurisdiction_research','Charter / VIP commercial operating scope','Charter and VIP services are service models, not one universal extra licence. Approval depends on the jurisdiction and whether the flights are commercial.','Valid operator approval for the flight type, aircraft and flight purpose; specific state permissions may apply.','Select service type and country; verify the applicable AOC/operating scope and obtain necessary permissions before commercial service.','https://www.easa.europa.eu/en/domains/air-operations/air-operator-certificate-aoc','needs_local_verification',NULL,NULL,false),
('DANGEROUS_GOODS','airline','operating_company','jurisdiction_research','Dangerous-goods transport authorisation','Special procedures and, where required, explicit competent-authority approvals for transporting regulated dangerous goods.','Applicable ICAO Technical Instructions, personnel training, approved procedures, packaging and any specific approvals/exemptions.','Establish compliant dangerous-goods procedures and obtain required state/operator approval for the proposed commodities and flights.','https://www.icao.int/Dangerous-Goods/Technical-Instructions','needs_local_verification',NULL,NULL,false),
('DOMESTIC_TRAFFIC','traffic_rights','route','jurisdiction_research','Domestic commercial traffic permission','An operator''s right to carry commercial traffic between two points in the relevant domestic jurisdiction.','Valid home-market operating authorisation and relevant country or integrated-market rights.','Verify the operating airline''s certificate/licence, market status and domestic route eligibility before scheduling.',NULL,'needs_local_verification',NULL,NULL,false),
('EU_AIRLINE_OPERATING_LICENCE','airline','operating_company','eu_reference','Commercial airline operating licence','Permits commercial passenger, cargo and/or mail services within its approved scope; EU reference, not a universal worldwide licence.','EU operator must satisfy Regulation (EC) 1008/2008 including financial and ownership/control conditions and a valid AOC.','Apply to the competent national authority; demonstrate required ownership, finance and operating readiness.','https://eur-lex.europa.eu/eli/reg/2008/1008/oj/eng','reference_only',NULL,NULL,false),
('FIFTH_FREEDOM','traffic_rights','route','jurisdiction_research','Fifth freedom rights','Allows certain traffic between foreign states on a service connected to the operator''s home country, only where granted.','Specific bilateral/multilateral route, stop and traffic rights and route conditions.','Check bilateral agreement provisions and state-specific route approval; never infer rights from airport accessibility.','https://wasa.icao.int/AboutWASA/WASAExplanatoryNotes','needs_local_verification',NULL,NULL,false),
('FOREIGN_BASE_PERMIT','traffic_rights','operating_company','game_proposal','Foreign hub / base authorisation','Game requirement for creating a base outside the airline''s home jurisdiction. Base rights are different from route traffic rights.','Existing Airlinerra foreign-base policy proposes capital, age, reputation, aircraft and traffic-rights gates; all disabled pending research.','Apply through future hub management; verify local operating rights and traffic rights before activating routes.',NULL,'reference_only',NULL,NULL,false),
('HOLDING_FORMATION','company','holding','game_proposal','Holding company registration','Creates a parent company for ownership and treasury, not an airline operating authority.','Original airline completes 60 operating game days; eligible ownership, capital and incorporation checks to be defined.','Apply from Holding after release; confirm name, jurisdiction, owner and pay the eventual registration fee.',NULL,'reference_only',NULL,NULL,false),
('INTEGRATED_MARKET','traffic_rights','route','eu_reference','Integrated aviation market access','Eligible airlines may have regional market privileges, such as within the EU, subject to operator licences and other restrictions.','Qualifying legal establishment, ownership/control, operator licence, AOC and any applicable regional market rules.','Verify qualifying carrier status and integration-market conditions; do not inherit rights from the nationality of the parent holding.','https://eur-lex.europa.eu/eli/reg/2008/1008/oj/eng','reference_only',NULL,NULL,false),
('NON_EU_MAINTENANCE','maintenance','operating_company','jurisdiction_research','National maintenance organisation approval','Non-EU maintenance business permissions depend on the applicable local authority; Part-145 is not a universal worldwide certificate.','Country-specific maintenance organisation, staffing and technical scope requirements.','Research and apply under the national regulator''s applicable maintenance organisation framework.',NULL,'needs_local_verification',NULL,NULL,false),
('PART145_MAINTENANCE','maintenance','operating_company','eu_reference','Part-145 maintenance organisation approval','Enables maintenance within the organisation''s approved scope under EU Part-145; owning an airline does not grant this approval.','Approved facilities, staff, quality/safety system, manuals, tools and scope of work; relevant maintenance certifying staff.','Apply for Part-145 approval with the competent aviation authority and maintain the approved rating/scope.','https://www.easa.europa.eu/en/the-agency/faqs/part-145','reference_only',NULL,NULL,false),
('SEVENTH_FREEDOM','traffic_rights','route','jurisdiction_research','Seventh freedom rights','Stand-alone commercial services between two foreign states, only if allowed by the applicable market agreements.','Verified agreement covering the operator and the relevant foreign markets.','Apply for or verify market access under the relevant treaty or integrated-market mechanism.','https://www.icao.int/sustainability/Documents/Compendium_FairCompetition/the%20evolution%20of%20network%20competution%20in%20transtl%20aviation%20and%20the%20effects%20of%20regulatoty%20libveralisatino%202009.pdf','needs_local_verification',NULL,NULL,false),
('SUBSIDIARY_FORMATION','company','holding','game_proposal','Subsidiary company formation','Creates a separately funded legal business owned by the holding.','Parent must have available capital, valid ownership, and comply with country-specific company formation rules.','Select subsidiary type and country, register it, then fund it through an audited equity injection or intercompany loan.',NULL,'reference_only',NULL,NULL,false),
('THIRD_FOURTH_FREEDOM','traffic_rights','route','jurisdiction_research','Third / fourth freedom rights','Commercial transport from the operator''s home state to another country and return, as granted by international arrangements.','Relevant air-services agreement, market access and operator designation or permissions.','Check the operator country, origin/destination states and applicable air-services agreement; obtain required operating permits.','https://wasa.icao.int/AboutWASA/WASAExplanatoryNotes','needs_local_verification',NULL,NULL,false)
on conflict(permission_code) do update set
 category=excluded.category,holder_scope=excluded.holder_scope,
 reference_basis=excluded.reference_basis,title=excluded.title,purpose=excluded.purpose,
 requirements=excluded.requirements,application_guidance=excluded.application_guidance,
 source_url=excluded.source_url,research_status=excluded.research_status,
 updated_at=now()
where airlinerra_game.business_permission_catalog_v1.enabled_in_game=false;
